function(container, apiUrl, tables) {
  // 初期化処理
  const storeSelect = container.querySelector('#store-select');
  const periodStart = container.querySelector('#period-start');
  const periodEnd = container.querySelector('#period-end');

  // 今日の日付を設定
  const today = new Date();
  const startOfMonth = new Date(today.getFullYear(), today.getMonth(), 1);
  periodStart.value = startOfMonth.toISOString().split('T')[0];
  periodEnd.value = today.toISOString().split('T')[0];

  // 店舗データの読み込み
  async function loadStores() {
    try {
      const stores = await window.aivicApi.list(1); // 店舗マスタ
      if (stores) {
        storeSelect.innerHTML = '<option value="">全店舗</option>' + 
          stores.filter(s => s.有効フラグ).map(s => 
            `<option value="${s.店舗ID}">${s.店舗名}</option>`
          ).join('');
      }
    } catch (error) {
      console.error('店舗データの読み込みに失敗:', error);
    }
  }

  // KPI計算関数
  function calculateKPIs(salesData, forecastData, orderData) {
    const currentMonth = new Date().toISOString().slice(0, 7);
    const lastMonth = new Date(new Date().setMonth(new Date().getMonth() - 1)).toISOString().slice(0, 7);

    // 今月の売上
    const currentSales = salesData
      .filter(s => s.売上日?.slice(0, 7) === currentMonth)
      .reduce((sum, s) => sum + (s.売上金額 || 0), 0);

    // 先月の売上
    const lastSales = salesData
      .filter(s => s.売上日?.slice(0, 7) === lastMonth)
      .reduce((sum, s) => sum + (s.売上金額 || 0), 0);

    const salesChange = lastSales > 0 ? ((currentSales - lastSales) / lastSales * 100) : 0;

    // 予測精度計算
    const accuracyData = forecastData.filter(f => f.実績数量 && f.予測数量);
    const accuracy = accuracyData.length > 0 ? 
      accuracyData.reduce((sum, f) => {
        const error = Math.abs(f.実績数量 - f.予測数量) / Math.max(f.実績数量, 1);
        return sum + (1 - error);
      }, 0) / accuracyData.length * 100 : 0;

    // 発注件数
    const currentOrders = orderData.filter(o => o.発注日?.slice(0, 7) === currentMonth).length;
    const lastOrders = orderData.filter(o => o.発注日?.slice(0, 7) === lastMonth).length;
    const orderChange = lastOrders > 0 ? ((currentOrders - lastOrders) / lastOrders * 100) : 0;

    return {
      currentSales,
      salesChange,
      accuracy,
      currentOrders,
      orderChange
    };
  }

  // KPI表示更新
  function updateKPIs(kpis) {
    container.querySelector('#monthly-sales').textContent = 
      `¥${kpis.currentSales.toLocaleString()}`;
    container.querySelector('#sales-change').textContent = 
      `前月比 ${kpis.salesChange >= 0 ? '+' : ''}${kpis.salesChange.toFixed(1)}%`;
    container.querySelector('#prediction-accuracy').textContent = 
      `${kpis.accuracy.toFixed(1)}%`;
    container.querySelector('#order-count').textContent = 
      `${kpis.currentOrders}件`;
    container.querySelector('#order-change').textContent = 
      `前月比 ${kpis.orderChange >= 0 ? '+' : ''}${kpis.orderChange.toFixed(1)}%`;
  }

  // 発注ステータス更新
  function updateOrderStatus(orderData) {
    const statusCounts = {
      pending: orderData.filter(o => o.発注ステータス === '未発注').length,
      ordered: orderData.filter(o => o.発注ステータス === '発注済').length,
      shipping: orderData.filter(o => o.発注ステータス === '配送中').length,
      completed: orderData.filter(o => o.発注ステータス === '完了').length
    };

    container.querySelector('#status-pending').textContent = statusCounts.pending;
    container.querySelector('#status-ordered').textContent = statusCounts.ordered;
    container.querySelector('#status-shipping').textContent = statusCounts.shipping;
    container.querySelector('#status-completed').textContent = statusCounts.completed;
  }

  // 在庫アラート更新
  function updateStockAlerts(salesData, orderData) {
    // 簡易的な在庫不足判定（実際の在庫データがないため売上ベースで推定）
    const productSales = {};
    salesData.forEach(s => {
      if (!productSales[s.商品ID]) productSales[s.商品ID] = 0;
      productSales[s.商品ID] += s.販売数量 || 0;
    });

    const alertCount = Math.floor(Object.keys(productSales).length * 0.1); // 10%の商品でアラート想定

    container.querySelector('#stock-alerts').textContent = `${alertCount}件`;
    container.querySelector('#alert-details').textContent = 
      alertCount > 0 ? `${alertCount}商品で在庫不足` : '要確認商品なし';
  }

  // イベント・季節情報更新
  function updateEventSeasonInfo(eventData, seasonData) {
    const infoContainer = container.querySelector('#event-season-info');
    const today = new Date();
    const currentMonth = today.getMonth() + 1;

    // 近日のイベント
    const upcomingEvents = eventData
      .filter(e => new Date(e.開始日時) >= today)
      .slice(0, 3);

    // 現在の季節情報
    const currentSeason = seasonData.find(s => s.月 === currentMonth);

    let html = '';

    if (currentSeason) {
      html += `<div class="season-item">${currentSeason.季節区分} (係数: ${currentSeason.季節係数}%)</div>`;
    }

    if (upcomingEvents.length > 0) {
      html += upcomingEvents.map(e => 
        `<div class="event-item">
          <span class="event-name">${e.イベント名}</span>
          <span class="event-impact">影響度: ${e.影響度}</span>
        </div>`
      ).join('');
    }

    if (!html) {
      html = '<div class="loading">特記事項なし</div>';
    }

    infoContainer.innerHTML = html;
  }

  // グラフ初期化
  function initCharts(salesData, forecastData, weatherData) {
    // 売上トレンドグラフ
    const salesCtx = container.querySelector('#sales-trend-chart').getContext('2d');
    const monthlySales = {};

    salesData.forEach(s => {
      const month = s.売上日?.slice(0, 7);
      if (month) {
        if (!monthlySales[month]) monthlySales[month] = 0;
        monthlySales[month] += s.売上金額 || 0;
      }
    });

    const salesLabels = Object.keys(monthlySales).sort().slice(-6);
    const salesValues = salesLabels.map(m => monthlySales[m] || 0);

    new Chart(salesCtx, {
      type: 'line',
      data: {
        labels: salesLabels,
        datasets: [{
          label: '売上金額',
          data: salesValues,
          borderColor: '#4a90e2',
          backgroundColor: 'rgba(74, 144, 226, 0.1)',
          tension: 0.4
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        scales: {
          y: {
            beginAtZero: true,
            ticks: { color: '#9fb0d1' },
            grid: { color: 'rgba(159, 176, 209, 0.1)' }
          },
          x: {
            ticks: { color: '#9fb0d1' },
            grid: { color: 'rgba(159, 176, 209, 0.1)' }
          }
        },
        plugins: {
          legend: { labels: { color: '#d0e4ff' } }
        }
      }
    });

    // 商品別売上ランキング
    const rankingCtx = container.querySelector('#product-ranking-chart').getContext('2d');
    const productSales = {};

    salesData.forEach(s => {
      if (!productSales[s.商品ID]) productSales[s.商品ID] = 0;
      productSales[s.商品ID] += s.売上金額 || 0;
    });

    const topProducts = Object.entries(productSales)
      .sort(([,a], [,b]) => b - a)
      .slice(0, 10);

    new Chart(rankingCtx, {
      type: 'bar',
      data: {
        labels: topProducts.map(([id,]) => `商品${id.slice(-4)}`),
        datasets: [{
          label: '売上金額',
          data: topProducts.map(([,sales]) => sales),
          backgroundColor: '#4a90e2'
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        indexAxis: 'y',
        scales: {
          y: {
            ticks: { color: '#9fb0d1' },
            grid: { color: 'rgba(159, 176, 209, 0.1)' }
          },
          x: {
            ticks: { color: '#9fb0d1' },
            grid: { color: 'rgba(159, 176, 209, 0.1)' }
          }
        },
        plugins: {
          legend: { labels: { color: '#d0e4ff' } }
        }
      }
    });

    // 天候影響分析
    const weatherCtx = container.querySelector('#weather-impact-chart').getContext('2d');
    const weatherSales = {};

    weatherData.forEach(w => {
      const date = w.観測日?.slice(0, 10);
      const daysSales = salesData
        .filter(s => s.売上日?.slice(0, 10) === date)
        .reduce((sum, s) => sum + (s.売上金額 || 0), 0);

      if (daysSales > 0 && w.平均気温) {
        const tempRange = Math.floor(w.平均気温 / 5) * 5;
        if (!weatherSales[tempRange]) weatherSales[tempRange] = [];
        weatherSales[tempRange].push(daysSales);
      }
    });

    const tempLabels = Object.keys(weatherSales).sort((a, b) => a - b);
    const avgSales = tempLabels.map(temp => {
      const sales = weatherSales[temp];
      return sales.reduce((sum, s) => sum + s, 0) / sales.length;
    });

    new Chart(weatherCtx, {
      type: 'scatter',
      data: {
        datasets: [{
          label: '気温別平均売上',
          data: tempLabels.map((temp, i) => ({ x: temp, y: avgSales[i] })),
          backgroundColor: '#ff6a00',
          borderColor: '#ff6a00'
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        scales: {
          y: {
            beginAtZero: true,
            title: { display: true, text: '売上金額', color: '#9fb0d1' },
            ticks: { color: '#9fb0d1' },
            grid: { color: 'rgba(159, 176, 209, 0.1)' }
          },
          x: {
            title: { display: true, text: '平均気温(℃)', color: '#9fb0d1' },
            ticks: { color: '#9fb0d1' },
            grid: { color: 'rgba(159, 176, 209, 0.1)' }
          }
        },
        plugins: {
          legend: { labels: { color: '#d0e4ff' } }
        }
      }
    });
  }

  // データ読み込みとダッシュボード更新
  async function loadDashboard() {
    try {
      const [salesData, forecastData, orderData, eventData, seasonData, weatherData] = await Promise.all([
        window.aivicApi.list(3), // 売上実績データ
        window.aivicApi.list(9), // 需要予測結果
        window.aivicApi.list(10), // 発注データ
        window.aivicApi.list(6), // イベントデータ
        window.aivicApi.list(7), // 季節情報データ
        window.aivicApi.list(4)  // 天候データ
      ]);

      if (salesData && forecastData && orderData) {
        const kpis = calculateKPIs(salesData, forecastData, orderData);
        updateKPIs(kpis);
        updateOrderStatus(orderData);
        updateStockAlerts(salesData, orderData);

        if (eventData && seasonData) {
          updateEventSeasonInfo(eventData, seasonData);
        }

        if (weatherData) {
          initCharts(salesData, forecastData, weatherData);
        }
      }
    } catch (error) {
      console.error('ダッシュボードデータの読み込みに失敗:', error);
      container.querySelector('#event-season-info').innerHTML = 
        '<div class="loading">データの取得に失敗しました。しばらく時間をおいて再度お試しください。</div>';
    }
  }

  // 店舗選択変更イベント
  storeSelect.addEventListener('change', loadDashboard);

  // 期間選択変更イベント
  periodStart.addEventListener('change', loadDashboard);
  periodEnd.addEventListener('change', loadDashboard);

  // アラート詳細クリックイベント
  container.querySelector('#alert-details').addEventListener('click', () => {
    window.showScreen('scr-1778591945891'); // 在庫照会画面
  });

  // 初期データ読み込み
  loadStores();
  loadDashboard();
}
